B.bbc=s(["Before Christ","Anno Domini"],t.s)
B.bDa=new A.fs("Who We Are","Saksham Foundation is a registered charitable organisation headquartered in Bengaluru, Karnataka. Founded in 2008, we work across education, child welfare, healthcare, and community development to uplift underserved communities across South India.")
B.bDl=new A.fs("Our Mission","To empower every child and family we serve with access to quality education, healthcare, and livelihood support \u2014 building a more equitable society, one community at a time.")
B.bD8=new A.fs("Our Impact","15,000+ children supported  \xb7  \u20b98.2 Cr+ raised  \xb7  48 partner NGOs  \xb7  12 districts reached\n\nEvery rupee donated is tracked, accounted for, and directed toward maximum beneficiary impact.")
B.bDm=new A.fs("Certifications & Registrations","\u2726 80G & 12A Tax Exemption\n\u2726 FCRA Licensed (Ministry of Home Affairs)\n\u2726 CSR-1 Registered (MCA)\n\u2726 GiveIndia Verified NGO\n\u2726 ISO 9001:2015 Quality Management")
B.bDn=new A.fs("This App","The Saksham Admin App is a purpose-built tool for staff and volunteers to manage donors, track donations, monitor student progress, and generate impact reports \u2014 all from a single mobile platform.")
B.bDf=new A.fs("Contact Us","Saksham Foundation\nNo. 42, NGO Campus, HSR Layout\nBengaluru \u2013 560067, Karnataka\n\nEmail: info@sakshamfoundation.org\nPhone: +91 80 2345 6789\nWebsite: www.sakshamfoundation.org")
B.bbf=s([B.bDa,B.bDl,B.bD8,B.bDm,B.bDn,B.bDf],t.HP)
B.ka={q:0,a:1}
B.bdA=new A.c6(B.ka,["How do I add a new donor?","Go to Donors \u2192 tap the + button \u2192 fill in donor details and tap Save. The donor will appear in your list immediately."],t.l)
B.bdx=new A.c6(B.ka,["Can I edit a donation after saving?","Yes. Open the donation from the Donations screen, tap the edit icon in the top right, make changes, and tap Save."],t.l)
B.bdy=new A.c6(B.ka,["How does a Payment Link work?","Go to Payment Links, fill in the amount and purpose, tap Generate. Share the link via WhatsApp, SMS, or Email directly from the app."],t.l)
B.bdz=new A.c6(B.ka,["Is my data backed up automatically?","Yes. When Auto Backup is enabled (Settings \u2192 Backup & Sync), data is backed up to the cloud every night at midnight."],t.l)
B.bdv=new A.c6(B.ka,["How do I export a report?","Go to Settings \u2192 Export Data, choose format (PDF / Excel / CSV), select date range and data types, then tap Export."],t.l)
B.bdw=new A.c6(B.ka,["Who can I contact for urgent help?","Call +91 80 2345 6789 (Mon\u2013Fri, 9 AM\u20136 PM IST) or email support@sakshamfoundation.org. We respond within 4 business hours."],t.l)
B.bbg=s([B.bdA,B.bdx,B.bdy,B.bdz,B.bdv,B.bdw],A.at("w<aq<c,c>>"))
